// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements microarchitecture.md (holding registers,
// state-only READY, one outstanding transaction per direction).
module axi4_lite_regs #(
    parameter integer ADDR_WIDTH = 4,
    parameter integer DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

    localparam integer STRB_WIDTH  = DATA_WIDTH / 8;
    localparam [1:0]   RESP_OKAY   = 2'b00;
    localparam [1:0]   RESP_SLVERR = 2'b10;

    // ------------------------------------------------------------------
    // State
    // ------------------------------------------------------------------
    reg                  aw_held;
    reg                  w_held;
    reg                  bvalid_q;
    reg  [1:0]           bresp_q;
    reg                  rvalid_q;
    reg  [1:0]           rresp_q;
    reg  [DATA_WIDTH-1:0] rdata_q;

    // Holding registers (datapath, not reset; qualified by the held flags)
    reg  [ADDR_WIDTH-1:0] aw_addr_q;
    reg  [DATA_WIDTH-1:0] w_data_q;
    reg  [STRB_WIDTH-1:0] w_strb_q;

    // Register file
    reg  [DATA_WIDTH-1:0] reg0;
    reg  [DATA_WIDTH-1:0] reg1;
    reg  [DATA_WIDTH-1:0] reg2;
    reg  [DATA_WIDTH-1:0] reg3;

    // ------------------------------------------------------------------
    // Handshakes: READY is a function of state only
    // ------------------------------------------------------------------
    wire awready_w = !aw_held && !bvalid_q;
    wire wready_w  = !w_held  && !bvalid_q;
    wire arready_w = !rvalid_q;

    wire aw_hs = s_axil_awvalid && awready_w;
    wire w_hs  = s_axil_wvalid  && wready_w;
    wire ar_hs = s_axil_arvalid && arready_w;

    // The write fires on the edge that completes the AW/W pair
    wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

    wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
    wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
    wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

    // Address decode: mapped when word aligned and within the 16-byte window
    wire wr_mapped = (wr_addr[1:0] == 2'b00) &&
                     ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
    wire ar_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                     ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

    wire [1:0] wr_idx = wr_addr[3:2];

    // Byte mask from the strobes: bit n of wstrb enables bits 8n+7:8n
    wire [DATA_WIDTH-1:0] wr_mask;
    genvar g;
    generate
        for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_mask
            assign wr_mask[8*g +: 8] = {8{wr_strb[g]}};
        end
    endgenerate

    wire [3:0] reg_we;
    assign reg_we[0] = do_write && wr_mapped && (wr_idx == 2'd0);
    assign reg_we[1] = do_write && wr_mapped && (wr_idx == 2'd1);
    assign reg_we[2] = do_write && wr_mapped && (wr_idx == 2'd2);
    assign reg_we[3] = do_write && wr_mapped && (wr_idx == 2'd3);

    // Read mux (combinational, fully assigned: no latch)
    reg [DATA_WIDTH-1:0] rd_sel;
    always @(*) begin
        case (s_axil_araddr[3:2])
            2'd0:    rd_sel = reg0;
            2'd1:    rd_sel = reg1;
            2'd2:    rd_sel = reg2;
            2'd3:    rd_sel = reg3;
            default: rd_sel = {DATA_WIDTH{1'b0}};
        endcase
    end

    // ------------------------------------------------------------------
    // Control, responses and register file (synchronous active-low reset)
    // ------------------------------------------------------------------
    always @(posedge aclk) begin
        if (!aresetn) begin
            aw_held  <= 1'b0;
            w_held   <= 1'b0;
            bvalid_q <= 1'b0;
            bresp_q  <= RESP_OKAY;
            rvalid_q <= 1'b0;
            rresp_q  <= RESP_OKAY;
            rdata_q  <= {DATA_WIDTH{1'b0}};
            reg0     <= {DATA_WIDTH{1'b0}};
            reg1     <= {DATA_WIDTH{1'b0}};
            reg2     <= {DATA_WIDTH{1'b0}};
            reg3     <= {DATA_WIDTH{1'b0}};
        end else begin
            // Held flags
            if (do_write) begin
                aw_held <= 1'b0;
                w_held  <= 1'b0;
            end else begin
                if (aw_hs) aw_held <= 1'b1;
                if (w_hs)  w_held  <= 1'b1;
            end

            // Write response
            if (do_write) begin
                bvalid_q <= 1'b1;
                bresp_q  <= wr_mapped ? RESP_OKAY : RESP_SLVERR;
            end else if (bvalid_q && s_axil_bready) begin
                bvalid_q <= 1'b0;
            end

            // Read response
            if (ar_hs) begin
                rvalid_q <= 1'b1;
                rresp_q  <= ar_mapped ? RESP_OKAY : RESP_SLVERR;
                rdata_q  <= ar_mapped ? rd_sel : {DATA_WIDTH{1'b0}};
            end else if (rvalid_q && s_axil_rready) begin
                rvalid_q <= 1'b0;
            end

            // Register file, byte-merged by the strobes
            if (reg_we[0]) reg0 <= (reg0 & ~wr_mask) | (wr_data & wr_mask);
            if (reg_we[1]) reg1 <= (reg1 & ~wr_mask) | (wr_data & wr_mask);
            if (reg_we[2]) reg2 <= (reg2 & ~wr_mask) | (wr_data & wr_mask);
            if (reg_we[3]) reg3 <= (reg3 & ~wr_mask) | (wr_data & wr_mask);
        end
    end

    // Holding registers: capture the half that arrives first
    always @(posedge aclk) begin
        if (aw_hs && !do_write) begin
            aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs && !do_write) begin
            w_data_q <= s_axil_wdata;
            w_strb_q <= s_axil_wstrb;
        end
    end

    // ------------------------------------------------------------------
    // Outputs
    // ------------------------------------------------------------------
    assign s_axil_awready = awready_w;
    assign s_axil_wready  = wready_w;
    assign s_axil_arready = arready_w;
    assign s_axil_bvalid  = bvalid_q;
    assign s_axil_bresp   = bresp_q;
    assign s_axil_rvalid  = rvalid_q;
    assign s_axil_rresp   = rresp_q;
    assign s_axil_rdata   = rdata_q;

    // ------------------------------------------------------------------
    // Design-intent properties (read only with read -formal; unproven here)
    // ------------------------------------------------------------------
`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge aclk) f_past_valid <= 1'b1;

    // Manager: reset on the first cycle, VALIDs low while in reset
    always @(*) begin
        if (!f_past_valid) assume(!aresetn);
        if (!aresetn) begin
            assume(!s_axil_awvalid);
            assume(!s_axil_wvalid);
            assume(!s_axil_arvalid);
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && $past(aresetn) && aresetn) begin
            // Manager holds VALID and payload until READY
            if ($past(s_axil_awvalid && !s_axil_awready)) begin
                assume(s_axil_awvalid);
                assume(s_axil_awaddr == $past(s_axil_awaddr));
            end
            if ($past(s_axil_wvalid && !s_axil_wready)) begin
                assume(s_axil_wvalid);
                assume(s_axil_wdata == $past(s_axil_wdata));
                assume(s_axil_wstrb == $past(s_axil_wstrb));
            end
            if ($past(s_axil_arvalid && !s_axil_arready)) begin
                assume(s_axil_arvalid);
                assume(s_axil_araddr == $past(s_axil_araddr));
            end
            // Subordinate holds B and R, with stable payload, until taken
            if ($past(bvalid_q && !s_axil_bready)) begin
                assert(bvalid_q);
                assert(bresp_q == $past(bresp_q));
            end
            if ($past(rvalid_q && !s_axil_rready)) begin
                assert(rvalid_q);
                assert(rresp_q == $past(rresp_q));
                assert(rdata_q == $past(rdata_q));
            end
        end
        // Responses low after reset
        if (f_past_valid && !$past(aresetn)) begin
            assert(!bvalid_q);
            assert(!rvalid_q);
            assert(!aw_held);
            assert(!w_held);
        end
        // A response appears only after an accepted request, one cycle later
        if (f_past_valid && $past(aresetn) && !$past(bvalid_q) && bvalid_q)
            assert($past(do_write));
        if (f_past_valid && $past(aresetn) && !$past(rvalid_q) && rvalid_q)
            assert($past(ar_hs));
        // Response code follows the address policy
        if (f_past_valid && $past(aresetn) && $past(do_write))
            assert(bresp_q == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR));
    end

    always @(*) begin
        if (f_past_valid) begin
            assert(!(aw_held && w_held));
            if (bvalid_q) assert(!aw_held && !w_held);
            assert((bresp_q == RESP_OKAY) || (bresp_q == RESP_SLVERR));
            assert((rresp_q == RESP_OKAY) || (rresp_q == RESP_SLVERR));
            if (rresp_q == RESP_SLVERR) assert(rdata_q == {DATA_WIDTH{1'b0}});
        end
    end

    always @(posedge aclk) begin
        if (f_past_valid && aresetn) begin
            cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_OKAY));
            cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_SLVERR));
            cover(s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_OKAY));
            cover(s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_SLVERR));
            cover(aw_held);
            cover(w_held);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
