// Self-checking directed testbench for axi4_lite_regs.
// Inputs are driven just after the falling edge; handshakes are decided from
// values sampled before the rising edge (READY depends on state only).
module axi4_lite_regs_tb;

  localparam [1:0] OKAY   = 2'b00;
  localparam [1:0] SLVERR = 2'b10;

  reg         aclk;
  reg         aresetn;
  reg  [3:0]  awaddr;
  reg         awvalid;
  wire        awready;
  reg  [31:0] wdata;
  reg  [3:0]  wstrb;
  reg         wvalid;
  wire        wready;
  wire [1:0]  bresp;
  wire        bvalid;
  reg         bready;
  reg  [3:0]  araddr;
  reg         arvalid;
  wire        arready;
  wire [31:0] rdata;
  wire [1:0]  rresp;
  wire        rvalid;
  reg         rready;

  integer        passed;
  integer        failed;
  integer        test_id;
  integer        k;
  reg            done;
  reg [8*64-1:0] nonce;
  reg [31:0]     model [0:3];
  reg [63:0]     t0;
  reg [63:0]     t1;
  reg [63:0]     dt;

  axi4_lite_regs #(.ADDR_WIDTH(4), .DATA_WIDTH(32)) dut (
    .aclk           (aclk),
    .aresetn        (aresetn),
    .s_axil_awaddr  (awaddr),
    .s_axil_awvalid (awvalid),
    .s_axil_awready (awready),
    .s_axil_wdata   (wdata),
    .s_axil_wstrb   (wstrb),
    .s_axil_wvalid  (wvalid),
    .s_axil_wready  (wready),
    .s_axil_bresp   (bresp),
    .s_axil_bvalid  (bvalid),
    .s_axil_bready  (bready),
    .s_axil_araddr  (araddr),
    .s_axil_arvalid (arvalid),
    .s_axil_arready (arready),
    .s_axil_rdata   (rdata),
    .s_axil_rresp   (rresp),
    .s_axil_rvalid  (rvalid),
    .s_axil_rready  (rready)
  );

  initial begin
    aclk = 1'b0;
    forever #5 aclk = ~aclk;
  end

  // ---------------------------------------------------------------------
  // Checking helpers
  // ---------------------------------------------------------------------
  task check1;
    input integer tag;
    input         cond;
    begin
      if (cond === 1'b1) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("test %0d check %0d failed at %0t", test_id, tag, $time);
      end
    end
  endtask

  task check32;
    input integer tag;
    input [31:0]  got;
    input [31:0]  exp;
    begin
      if (got === exp) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("test %0d check %0d failed at %0t: got %h, expected %h",
               test_id, tag, $time, got, exp);
      end
    end
  endtask

  function [31:0] merge;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  strb;
    begin
      merge = old_v;
      if (strb[0]) merge[7:0]   = new_v[7:0];
      if (strb[1]) merge[15:8]  = new_v[15:8];
      if (strb[2]) merge[23:16] = new_v[23:16];
      if (strb[3]) merge[31:24] = new_v[31:24];
    end
  endfunction

  // ---------------------------------------------------------------------
  // One write. Entered just after a falling edge; returns just after one.
  // aw_delay / w_delay: cycles before each VALID rises.
  // b_delay: cycles BREADY stays low after BVALID rises.
  // ---------------------------------------------------------------------
  task axil_write;
    input [3:0]   addr;
    input [31:0]  data;
    input [3:0]   strb;
    input integer aw_delay;
    input integer w_delay;
    input integer b_delay;
    integer   cyc;
    integer   lat;
    integer   n;
    reg       aw_done;
    reg       w_done;
    reg       aw_now;
    reg       w_now;
    reg       mapped;
    reg [1:0] exp_resp;
    begin
      mapped   = (addr[1:0] == 2'b00);
      exp_resp = mapped ? OKAY : SLVERR;
      aw_done  = 1'b0;
      w_done   = 1'b0;
      cyc      = 0;
      while (!(aw_done && w_done) && (cyc < 64)) begin
        awvalid = !aw_done && (cyc >= aw_delay);
        awaddr  = awvalid ? addr : ~addr;
        wvalid  = !w_done && (cyc >= w_delay);
        wdata   = wvalid ? data : ~data;
        wstrb   = wvalid ? strb : ~strb;
        check1(1, !bvalid);
        if (aw_done) check1(2, !awready);
        if (w_done)  check1(3, !wready);
        aw_now = awvalid && awready;
        w_now  = wvalid && wready;
        @(posedge aclk);
        if (aw_now) aw_done = 1'b1;
        if (w_now)  w_done  = 1'b1;
        cyc = cyc + 1;
        @(negedge aclk);
      end
      awvalid = 1'b0;
      wvalid  = 1'b0;
      awaddr  = ~addr;
      wdata   = ~data;
      wstrb   = ~strb;
      check1(4, aw_done && w_done);
      lat = 1;
      while (!bvalid && (lat < 4)) begin
        @(negedge aclk);
        lat = lat + 1;
      end
      check1(5, bvalid);
      check1(6, lat <= 2);
      for (n = 0; n < b_delay; n = n + 1) begin
        check1(7, bvalid);
        check32(8, {30'd0, bresp}, {30'd0, exp_resp});
        check1(9, !awready && !wready);
        @(negedge aclk);
      end
      bready = 1'b1;
      check1(10, bvalid);
      check32(11, {30'd0, bresp}, {30'd0, exp_resp});
      @(posedge aclk);
      @(negedge aclk);
      bready = 1'b0;
      check1(12, !bvalid);
      check1(13, awready && wready);
      if (mapped) model[addr[3:2]] = merge(model[addr[3:2]], data, strb);
    end
  endtask

  // ---------------------------------------------------------------------
  // One read. Same entry/exit convention as axil_write.
  // ---------------------------------------------------------------------
  task axil_read;
    input [3:0]   addr;
    input integer ar_delay;
    input integer r_delay;
    integer    cyc;
    integer    lat;
    integer    n;
    reg        ar_done;
    reg        ar_now;
    reg        mapped;
    reg [1:0]  exp_resp;
    reg [31:0] exp_data;
    begin
      mapped   = (addr[1:0] == 2'b00);
      exp_resp = mapped ? OKAY : SLVERR;
      exp_data = mapped ? model[addr[3:2]] : 32'h0;
      ar_done  = 1'b0;
      cyc      = 0;
      while (!ar_done && (cyc < 64)) begin
        arvalid = (cyc >= ar_delay);
        araddr  = arvalid ? addr : ~addr;
        check1(21, !rvalid);
        ar_now = arvalid && arready;
        @(posedge aclk);
        ar_done = ar_now;
        cyc = cyc + 1;
        @(negedge aclk);
      end
      arvalid = 1'b0;
      araddr  = ~addr;
      check1(22, ar_done);
      lat = 1;
      while (!rvalid && (lat < 4)) begin
        @(negedge aclk);
        lat = lat + 1;
      end
      check1(23, rvalid);
      check1(24, lat <= 2);
      for (n = 0; n < r_delay; n = n + 1) begin
        check1(25, rvalid);
        check32(26, {30'd0, rresp}, {30'd0, exp_resp});
        check32(27, rdata, exp_data);
        check1(28, !arready);
        @(negedge aclk);
      end
      rready = 1'b1;
      check1(29, rvalid);
      check32(30, {30'd0, rresp}, {30'd0, exp_resp});
      check32(31, rdata, exp_data);
      @(posedge aclk);
      @(negedge aclk);
      rready = 1'b0;
      check1(32, !rvalid);
      check1(33, arready);
    end
  endtask

  // ---------------------------------------------------------------------
  // Directed sequence
  // ---------------------------------------------------------------------
  initial begin
    passed  = 0;
    failed  = 0;
    test_id = 0;
    done    = 1'b0;
    nonce   = 512'd0;
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = 512'd0;

    aresetn = 1'b0;
    awaddr  = 4'h0;
    awvalid = 1'b0;
    wdata   = 32'h0;
    wstrb   = 4'h0;
    wvalid  = 1'b0;
    bready  = 1'b0;
    araddr  = 4'h0;
    arvalid = 1'b0;
    rready  = 1'b0;
    model[0] = 32'h0;
    model[1] = 32'h0;
    model[2] = 32'h0;
    model[3] = 32'h0;

    // Test 1: reset state
    test_id = 1;
    repeat (4) @(posedge aclk);
    @(negedge aclk);
    check1(100, !bvalid);
    check1(101, !rvalid);
    check32(102, {30'd0, bresp}, {30'd0, OKAY});
    check32(103, {30'd0, rresp}, {30'd0, OKAY});
    check32(104, rdata, 32'h0);
    aresetn = 1'b1;
    check1(105, awready);
    check1(106, wready);
    check1(107, arready);

    // Test 2: reset values of every register
    test_id = 2;
    for (k = 0; k < 4; k = k + 1) axil_read({k[1:0], 2'b00}, 0, 0);

    // Test 3: write then read every register (AW and W together)
    test_id = 3;
    axil_write(4'h0, 32'hA5A5_0001, 4'hF, 0, 0, 0);
    axil_write(4'h4, 32'h0123_4567, 4'hF, 0, 0, 0);
    axil_write(4'h8, 32'h89AB_CDEF, 4'hF, 0, 0, 0);
    axil_write(4'hC, 32'hDEAD_BEEF, 4'hF, 0, 0, 0);
    for (k = 0; k < 4; k = k + 1) axil_read({k[1:0], 2'b00}, 0, 0);

    // Test 4: AW before W, W before AW, with gaps
    test_id = 4;
    axil_write(4'h4, 32'h1357_9BDF, 4'hF, 0, 3, 0);
    axil_write(4'h8, 32'h2468_ACE0, 4'hF, 4, 0, 0);
    axil_write(4'hC, 32'h0F0F_F0F0, 4'hF, 1, 0, 0);
    axil_write(4'h0, 32'hF0F0_0F0F, 4'hF, 0, 1, 0);
    for (k = 0; k < 4; k = k + 1) axil_read({k[1:0], 2'b00}, 0, 0);

    // Test 5: byte strobes, including all-zero
    test_id = 5;
    axil_write(4'h0, 32'h1122_3344, 4'hF, 0, 0, 0);
    axil_write(4'h0, 32'hAABB_CCDD, 4'b0101, 0, 0, 0);
    axil_read(4'h0, 0, 0);
    axil_write(4'h4, 32'h5566_7788, 4'b1000, 0, 0, 0);
    axil_write(4'h8, 32'h99AA_BBCC, 4'b0010, 0, 0, 0);
    axil_write(4'hC, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);
    axil_write(4'h4, 32'h0BAD_F00D, 4'b0110, 2, 0, 0);
    for (k = 0; k < 4; k = k + 1) axil_read({k[1:0], 2'b00}, 0, 0);

    // Test 6: B and R backpressure (payload must hold)
    test_id = 6;
    axil_write(4'h8, 32'hB0B0_B0B0, 4'hF, 0, 0, 5);
    axil_read(4'h8, 0, 6);
    axil_write(4'h9, 32'h1111_2222, 4'hF, 0, 2, 3);
    axil_read(4'hA, 1, 4);

    // Test 7: back-to-back transactions, one per two cycles
    test_id = 7;
    t0 = $time;
    axil_write(4'h0, 32'h0000_0010, 4'hF, 0, 0, 0);
    axil_write(4'h4, 32'h0000_0020, 4'hF, 0, 0, 0);
    axil_write(4'h8, 32'h0000_0030, 4'hF, 0, 0, 0);
    axil_write(4'hC, 32'h0000_0040, 4'hF, 0, 0, 0);
    t1 = $time;
    dt = t1 - t0;
    check32(700, dt[31:0], 32'd80);
    t0 = $time;
    for (k = 0; k < 4; k = k + 1) axil_read({k[1:0], 2'b00}, 0, 0);
    t1 = $time;
    dt = t1 - t0;
    check32(701, dt[31:0], 32'd80);

    // Test 8: SLVERR policy for unmapped (misaligned) addresses
    test_id = 8;
    axil_write(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
    axil_write(4'h2, 32'hFFFF_FFFF, 4'hF, 1, 0, 0);
    axil_write(4'hE, 32'hFFFF_FFFF, 4'hF, 0, 1, 0);
    axil_write(4'h3, 32'hFFFF_FFFF, 4'hF, 0, 0, 2);
    for (k = 0; k < 4; k = k + 1) axil_read({k[1:0], 2'b00}, 0, 0);
    axil_read(4'h1, 0, 0);
    axil_read(4'h6, 0, 0);
    axil_read(4'hE, 0, 2);
    axil_read(4'hF, 0, 0);

    // Test 9: read and write in the same cycle; independent channels
    test_id = 9;
    awvalid = 1'b1; awaddr = 4'h4;
    wvalid  = 1'b1; wdata  = 32'h7777_1234; wstrb = 4'hF;
    arvalid = 1'b1; araddr = 4'h8;
    check1(900, awready && wready && arready);
    @(posedge aclk);
    @(negedge aclk);
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
    check1(901, bvalid);
    check1(902, rvalid);
    check32(903, {30'd0, bresp}, {30'd0, OKAY});
    check32(904, {30'd0, rresp}, {30'd0, OKAY});
    check32(905, rdata, model[2]);
    bready = 1'b1; rready = 1'b1;
    @(posedge aclk);
    @(negedge aclk);
    bready = 1'b0; rready = 1'b0;
    check1(906, !bvalid && !rvalid);
    model[1] = 32'h7777_1234;
    axil_read(4'h4, 0, 0);

    // Unmapped write and mapped read together; R taken while B stalls
    awvalid = 1'b1; awaddr = 4'h6;
    wvalid  = 1'b1; wdata  = 32'h5A5A_5A5A; wstrb = 4'hF;
    arvalid = 1'b1; araddr = 4'h4;
    @(posedge aclk);
    @(negedge aclk);
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
    check1(910, bvalid && rvalid);
    check32(911, rdata, model[1]);
    rready = 1'b1;
    @(posedge aclk);
    @(negedge aclk);
    rready = 1'b0;
    check1(912, !rvalid);
    check1(913, bvalid);
    check32(914, {30'd0, bresp}, {30'd0, SLVERR});
    check1(915, arready && !awready && !wready);
    axil_read(4'h0, 0, 0);
    check1(916, bvalid);
    check32(917, {30'd0, bresp}, {30'd0, SLVERR});
    bready = 1'b1;
    @(posedge aclk);
    @(negedge aclk);
    bready = 1'b0;
    check1(918, !bvalid);
    for (k = 0; k < 4; k = k + 1) axil_read({k[1:0], 2'b00}, 0, 0);

    // Test 10: reset during traffic
    test_id = 10;
    awvalid = 1'b1; awaddr = 4'h0;
    wvalid  = 1'b1; wdata  = 32'h1234_5678; wstrb = 4'hF;
    arvalid = 1'b1; araddr = 4'h4;
    @(posedge aclk);
    @(negedge aclk);
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
    check1(1000, bvalid && rvalid);
    aresetn = 1'b0;
    @(posedge aclk);
    @(negedge aclk);
    check1(1001, !bvalid);
    check1(1002, !rvalid);
    aresetn = 1'b1;
    model[0] = 32'h0;
    model[1] = 32'h0;
    model[2] = 32'h0;
    model[3] = 32'h0;
    check1(1003, awready && wready && arready);

    // Half-accepted write (AW only) is discarded by reset
    awvalid = 1'b1; awaddr = 4'h8;
    @(posedge aclk);
    @(negedge aclk);
    awvalid = 1'b0;
    check1(1004, !awready);
    check1(1005, wready);
    check1(1006, !bvalid);
    aresetn = 1'b0;
    @(posedge aclk);
    @(negedge aclk);
    aresetn = 1'b1;
    check1(1007, awready && wready && !bvalid);
    wvalid = 1'b1; wdata = 32'hCAFE_F00D; wstrb = 4'hF;
    @(posedge aclk);
    @(negedge aclk);
    wvalid = 1'b0; wdata = 32'h0; wstrb = 4'h0;
    repeat (3) begin
      check1(1008, !bvalid);
      check1(1009, !wready);
      check1(1010, awready);
      @(negedge aclk);
    end
    awvalid = 1'b1; awaddr = 4'hC;
    @(posedge aclk);
    @(negedge aclk);
    awvalid = 1'b0;
    check1(1011, bvalid);
    check32(1012, {30'd0, bresp}, {30'd0, OKAY});
    bready = 1'b1;
    @(posedge aclk);
    @(negedge aclk);
    bready = 1'b0;
    check1(1013, !bvalid);
    model[3] = 32'hCAFE_F00D;
    for (k = 0; k < 4; k = k + 1) axil_read({k[1:0], 2'b00}, 0, 0);

    // Verdict
    test_id = 99;
    done = 1'b1;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  // Watchdog: a hung handshake is a failed run
  initial begin
    #100000;
    if (!done) begin
      $error("watchdog: simulation did not complete");
      $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
      $finish;
    end
  end

endmodule

`default_nettype wire
